WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.ViewCount, p.Score, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS UserPostRank, COUNT(c.Id) AS CommentCount FROM Posts AS p LEFT JOIN Comments AS c ON p.Id = c.PostId WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR GROUP BY p.Id, p.Title, p.CreationDate, p.ViewCount, p.Score, p.OwnerUserId), TopPosts AS (SELECT rp.PostId, rp.Title, rp.CreationDate, rp.ViewCount, rp.Score, rp.CommentCount FROM RankedPosts AS rp WHERE rp.UserPostRank <= 3), UserBadges AS (SELECT u.Id AS UserId, COUNT(b.Id) AS BadgeCount, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id) SELECT p.PostId, p.Title, p.CreationDate, p.ViewCount, p.Score, p.CommentCount, u.DisplayName AS PostOwner, COALESCE(ub.BadgeCount, 0) AS UserBadgeCount, COALESCE(ub.BadgeNames, 'No Badges') AS UserBadges FROM TopPosts AS p INNER JOIN Users AS u ON p.PostId = u.Id LEFT JOIN UserBadges AS ub ON u.Id = ub.UserId WHERE p.CommentCount > 5 ORDER BY p.Score DESC NULLS FIRST, p.ViewCount ASC FETCH FIRST 10 ROWS ONLY